import textwrap
from pathlib import Path

from graphify.extract import extract_python
from graphify.ids import make_id


SRC = textwrap.dedent(
    '''
    import functools


    def get_connection():
        return 1


    def _get_connection():
        return 2


    def __(x):
        return x


    def helper():
        def inner():
            return 3
        return inner


    async def fetch():
        return 4


    @functools.lru_cache(maxsize=None)
    def cached():
        return 5


    class Repo:
        def save(self):
            pass

        def _save(self):
            pass

        def __save(self):
            pass

        def load(self):
            pass

        class Nested:
            def deep(self):
                pass


    class Lonely:
        def _a(self):
            pass

        def __a(self):
            pass
    '''
)


def _write(tmp_path: Path) -> Path:
    p = tmp_path / "pkg" / "store.py"
    p.parent.mkdir(parents=True)
    p.write_text(SRC, encoding="utf-8")
    return p


def test_keys_cover_module_functions_and_direct_methods(tmp_path):
    from graphify.extractors.engine import python_symbol_ids

    ids = python_symbol_ids(_write(tmp_path))
    assert set(ids) == {
        "get_connection", "_get_connection", "helper", "fetch", "cached",
        "Repo.save", "Repo._save", "Repo.__save", "Repo.load",
        "Lonely._a", "Lonely.__a",
    }


def test_values_match_python_extractor_node_ids(tmp_path):
    from graphify.extractors.engine import python_symbol_ids

    path = _write(tmp_path)
    ids = python_symbol_ids(path)
    extracted = {n["id"] for n in extract_python(path)["nodes"]}
    for key, nid in ids.items():
        assert nid in extracted, (key, nid)
    # every colliding name ends up on its own node
    assert len(set(ids.values())) == len(ids)


def test_public_member_keeps_plain_id_and_private_is_salted(tmp_path):
    from graphify.extractors.engine import python_symbol_ids

    ids = python_symbol_ids(_write(tmp_path), stem="pkg/store")
    assert ids["get_connection"] == make_id("pkg/store", "get_connection")
    assert ids["_get_connection"] != make_id("pkg/store", "get_connection")
    assert ids["_get_connection"].startswith(make_id("pkg/store", "get_connection") + "_")
    assert ids["helper"] == make_id("pkg/store", "helper")
    assert ids["cached"] == make_id("pkg/store", "cached")
    repo = make_id("pkg/store", "Repo")
    assert ids["Repo.save"] == make_id(repo, "save")
    assert ids["Repo.load"] == make_id(repo, "load")
    assert ids["Repo._save"] != ids["Repo.__save"]
    assert ids["Repo._save"].startswith(make_id(repo, "save") + "_")


def test_group_without_public_member_salts_everyone(tmp_path):
    from graphify.extractors.engine import python_symbol_ids

    ids = python_symbol_ids(_write(tmp_path), stem="pkg/store")
    plain = make_id(make_id("pkg/store", "Lonely"), "a")
    assert ids["Lonely._a"] != plain
    assert ids["Lonely.__a"] != plain
    assert ids["Lonely._a"] != ids["Lonely.__a"]


def test_file_without_definitions(tmp_path):
    from graphify.extractors.engine import python_symbol_ids

    p = tmp_path / "empty.py"
    p.write_text("X = 1\n", encoding="utf-8")
    assert python_symbol_ids(p) == {}

