import networkx as nx
import pytest

from graphify.wiki import plan_wiki_filenames, to_wiki


def _graph():
    G = nx.Graph()
    for nid, label in [("a", "parse()"), ("b", "Lexer"), ("c", "Parser"), ("d", "index()"), ("e", "Thing")]:
        G.add_node(nid, label=label, source_file=f"src/{nid}.py", file_type="code")
    G.add_edge("a", "b", relation="calls", confidence="EXTRACTED")
    G.add_edge("a", "c", relation="calls", confidence="INFERRED")
    G.add_edge("c", "d", relation="calls", confidence="EXTRACTED")
    G.add_edge("d", "e", relation="uses", confidence="AMBIGUOUS")
    return G


COMMUNITIES = {0: ["a", "b"], 1: ["c"], 2: ["ghost"], 3: ["d"], 4: ["e"]}
LABELS = {0: "Parser", 1: "parser", 2: "Gone", 3: "index", 4: "a/b: c (x)"}
GODS = [
    {"id": "a", "label": "parse()", "degree": 2},
    {"id": "zzz", "label": "Missing", "degree": 9},
    {"id": "c", "label": "Parser", "degree": 2},
]


def test_planned_names(tmp_path):
    plan = plan_wiki_filenames(_graph(), COMMUNITIES, tmp_path / "wiki", LABELS, GODS)
    assert plan["communities"] == {
        0: "Parser.md",
        1: "parser_2.md",
        3: "index_2.md",
        4: "a-b-_c_x.md",
    }
    assert plan["god_nodes"] == {"a": "parse.md", "c": "Parser_3.md"}


def test_plan_does_not_write(tmp_path):
    out = tmp_path / "wiki"
    plan_wiki_filenames(_graph(), COMMUNITIES, out, LABELS, GODS)
    assert not out.exists()


def test_plan_matches_to_wiki_output(tmp_path):
    out = tmp_path / "wiki"
    plan = plan_wiki_filenames(_graph(), COMMUNITIES, out, LABELS, GODS)
    to_wiki(_graph(), COMMUNITIES, out, community_labels=LABELS, god_nodes_data=GODS)
    on_disk = {p.name for p in out.glob("*.md")}
    planned = set(plan["communities"].values()) | set(plan["god_nodes"].values())
    assert on_disk == planned | {"index.md"}


def test_default_labels_and_no_gods(tmp_path):
    plan = plan_wiki_filenames(_graph(), {0: ["a", "b"], 1: ["c", "d", "e"]}, tmp_path)
    assert plan == {"communities": {0: "Community_0.md", 1: "Community_1.md"}, "god_nodes": {}}


def test_empty_or_all_stale_raises(tmp_path):
    with pytest.raises(ValueError):
        plan_wiki_filenames(_graph(), {}, tmp_path)
    with pytest.raises(ValueError):
        plan_wiki_filenames(_graph(), {0: ["nope"], 1: ["gone"]}, tmp_path)

