import copy

from graphify.extractors.terraform import redact_terraform_attributes

R = "[redacted]"


def test_key_based_redaction_recurses_into_maps_and_lists():
    attrs = {
        "instance_type": "t3.micro",
        "DB_Password": "hunter2",
        "tags": {"Name": "web", "api-key": "abc", "count": 3},
        "configs": [{"password": "p", "user": "admin"}, "plain", 7],
        "client_secret": {"nested": "whole value goes"},
        "ports": [80, 443],
    }
    before = copy.deepcopy(attrs)
    out = redact_terraform_attributes(attrs)
    assert out == {
        "instance_type": "t3.micro",
        "DB_Password": R,
        "tags": {"Name": "web", "api-key": R, "count": 3},
        "configs": [{"password": R, "user": "admin"}, "plain", 7],
        "client_secret": R,
        "ports": [80, 443],
    }
    assert attrs == before  # input untouched
    assert out is not attrs


def test_name_value_pair_idiom():
    attrs = {
        "environment": [
            {"name": "DB_PASSWORD", "value": "hunter2"},
            {"name": "REGION", "value": "eu-west-1"},
            {"Name": "STRIPE_TOKEN", "valueFrom": "arn:secret", "Value": "x"},
        ]
    }
    out = redact_terraform_attributes(attrs)
    assert out == {
        "environment": [
            {"name": "DB_PASSWORD", "value": R},
            {"name": "REGION", "value": "eu-west-1"},
            {"Name": "STRIPE_TOKEN", "valueFrom": R, "Value": R},
        ]
    }


def test_variable_and_output_label_or_sensitive_flag():
    v = redact_terraform_attributes(
        {"default": "s3cr3t", "type": "string"}, block_type="variable", label="db_token"
    )
    assert v == {"default": R, "type": "string"}

    plain = redact_terraform_attributes(
        {"default": "eu-west-1", "type": "string"}, block_type="variable", label="region"
    )
    assert plain == {"default": "eu-west-1", "type": "string"}

    o = redact_terraform_attributes(
        {"value": "conn", "sensitive": True}, block_type="output", label="endpoint"
    )
    assert o == {"value": R, "sensitive": True}

    o2 = redact_terraform_attributes(
        {"value": ["a", "b"], "sensitive": "true"}, block_type="output", label="hosts"
