from typing import Optional

from sqlalchemy.orm import Mapped, relationship
from sqlmodel import Field, Relationship, SQLModel
from sqlmodel.main import get_relationship_targets


class RtTeam(SQLModel, table=True):
    id: int | None = Field(default=None, primary_key=True)
    name: str
    heroes: list["RtHero"] = Relationship(back_populates="team")
    sponsor_id: int | None = Field(default=None, foreign_key="rtsponsor.id")
    sponsor: Optional["RtSponsor"] = Relationship()


class RtSponsor(SQLModel, table=True):
    id: int | None = Field(default=None, primary_key=True)


class RtHeroPowerLink(SQLModel, table=True):
    hero_id: int | None = Field(default=None, foreign_key="rthero.id", primary_key=True)
    power_id: int | None = Field(
        default=None, foreign_key="rtpower.id", primary_key=True
    )


class RtHero(SQLModel, table=True):
    id: int | None = Field(default=None, primary_key=True)
    name: str
    team_id: int | None = Field(default=None, foreign_key="rtteam.id")
    team: RtTeam | None = Relationship(back_populates="heroes")
    powers: Mapped[list["RtPower"]] = Relationship(
        back_populates="heroes", link_model=RtHeroPowerLink
    )
    mentor_team: RtTeam = Relationship(
        sa_relationship=relationship(
            "RtTeam", primaryjoin="RtHero.team_id == RtTeam.id", viewonly=True
        )
    )


class RtPower(SQLModel, table=True):
    id: int | None = Field(default=None, primary_key=True)
    name: str
    heroes: list[RtHero] = Relationship(
        back_populates="powers", link_model=RtHeroPowerLink
    )


class RtPlain(SQLModel, table=True):
    id: int | None = Field(default=None, primary_key=True)


class RtNonTable(SQLModel):
    name: str


def test_forward_refs_lists_and_optionals():
    targets = get_relationship_targets(RtTeam)
    assert targets == {"heroes": "RtHero", "sponsor": "RtSponsor"}
    assert list(targets) == ["heroes", "sponsor"]


def test_classes_mapped_and_sa_relationship():
    targets = get_relationship_targets(RtHero)
    assert targets == {
        "team": "RtTeam",
        "powers": "RtPower",
        "mentor_team": "RtTeam",
    }
    assert list(targets) == ["team", "powers", "mentor_team"]


def test_class_inside_list():
    assert get_relationship_targets(RtPower) == {"heroes": "RtHero"}


def test_values_are_strings():
    for model in (RtTeam, RtHero, RtPower):
        for value in get_relationship_targets(model).values():
            assert type(value) is str


def test_models_without_relationships():
    assert get_relationship_targets(RtPlain) == {}
    assert get_relationship_targets(RtNonTable) == {}
    assert get_relationship_targets(RtHeroPowerLink) == {}
    assert get_relationship_targets(RtSponsor) == {}
